-- READ-ONLY indexed-range screen; 2020 1h-to-<24h gaps, chunk 2; one archive per query.
SELECT gap_id, COUNT(*) row_count, SUM(outTemp IS NOT NULL) outTemp_nonnull, SUM(outTemp=0) outTemp_zero, SUM(outHumidity IS NOT NULL) outHumidity_nonnull, SUM(rain IS NOT NULL) rain_nonnull, SUM(rainRate IS NOT NULL) rainRate_nonnull, SUM(windSpeed IS NOT NULL) windSpeed_nonnull, SUM(windGust IS NOT NULL) windGust_nonnull, SUM(windDir IS NOT NULL) windDir_nonnull, SUM(barometer IS NOT NULL) barometer_nonnull, COUNT(DISTINCT usUnits) distinct_usUnits, COUNT(DISTINCT `interval`) distinct_interval
FROM (SELECT CASE WHEN dateTime>1600379400 AND dateTime<1600411200 THEN '2020:1600379400:1600411200' WHEN dateTime>1600452000 AND dateTime<1600458300 THEN '2020:1600452000:1600458300' WHEN dateTime>1600473600 AND dateTime<1600483800 THEN '2020:1600473600:1600483800' WHEN dateTime>1600483800 AND dateTime<1600491300 THEN '2020:1600483800:1600491300' WHEN dateTime>1600491300 AND dateTime<1600495500 THEN '2020:1600491300:1600495500' WHEN dateTime>1600551600 AND dateTime<1600563900 THEN '2020:1600551600:1600563900' WHEN dateTime>1600658400 AND dateTime<1600664100 THEN '2020:1600658400:1600664100' WHEN dateTime>1600665600 AND dateTime<1600670700 THEN '2020:1600665600:1600670700' WHEN dateTime>1602879900 AND dateTime<1602927000 THEN '2020:1602879900:1602927000' WHEN dateTime>1603353900 AND dateTime<1603374300 THEN '2020:1603353900:1603374300' WHEN dateTime>1603888200 AND dateTime<1603891800 THEN '2020:1603888200:1603891800' WHEN dateTime>1604053800 AND dateTime<1604085000 THEN '2020:1604053800:1604085000' WHEN dateTime>1605497400 AND dateTime<1605520500 THEN '2020:1605497400:1605520500' WHEN dateTime>1605533100 AND dateTime<1605539100 THEN '2020:1605533100:1605539100' WHEN dateTime>1605539100 AND dateTime<1605609900 THEN '2020:1605539100:1605609900' END gap_id, a.* FROM `weewx_WH1080`.archive a WHERE (dateTime>1600379400 AND dateTime<1600411200) OR (dateTime>1600452000 AND dateTime<1600458300) OR (dateTime>1600473600 AND dateTime<1600483800) OR (dateTime>1600483800 AND dateTime<1600491300) OR (dateTime>1600491300 AND dateTime<1600495500) OR (dateTime>1600551600 AND dateTime<1600563900) OR (dateTime>1600658400 AND dateTime<1600664100) OR (dateTime>1600665600 AND dateTime<1600670700) OR (dateTime>1602879900 AND dateTime<1602927000) OR (dateTime>1603353900 AND dateTime<1603374300) OR (dateTime>1603888200 AND dateTime<1603891800) OR (dateTime>1604053800 AND dateTime<1604085000) OR (dateTime>1605497400 AND dateTime<1605520500) OR (dateTime>1605533100 AND dateTime<1605539100) OR (dateTime>1605539100 AND dateTime<1605609900)) hits
GROUP BY gap_id ORDER BY gap_id;
